	out := strings.Join([]string{
		"0123456789012345678901234567890123456789 1 1 1",
		"boundary",
		`filename "\346\227\245.md"`,
		"\tline",
		"",
	}, "\n")
	lines, err := parsePorcelain(out)
	if err != nil {
		t.Fatal(err)
