func TestTrackedSymlinkIsUnverifiable(t *testing.T) {
	r := newRepo(t)
	r.write("real.md", "r\\n")
	r.write("other.md", "o\\n")
	if err := os.Symlink("real.md", filepath.Join(r.dir, "link.md")); err != nil {
