    seen=set(); stack=[]
    def dfs(u):
        if u in stack: return stack[stack.index(u):]+[u]
        if u in seen: return None
        seen.add(u); stack.append(u)
        for v in g.get(u,()):
            r=dfs(v)
            if r: return r
